<script setup lang="ts">import{defineAsyncComponent,ref}from'vue';import{ArrowLeft,Upload,FileMusic}from'lucide-vue-next';import{RouterLink}from'vue-router';const Viewer=defineAsyncComponent(()=>import('../components/OSMDViewer.vue'));const file=ref<File|null>(null),error=ref('');function choose(e:Event){const f=(e.target as HTMLInputElement).files?.[0];error.value='';if(!f)return;if(!/\.(xml|musicxml)$/i.test(f.name)){error.value='Por ahora selecciona un archivo .xml o .musicxml';return}file.value=f}</script><template><div class="page"><RouterLink to="/" class="mb-6 inline-flex items-center gap-2 text-sm font-bold text-[#698077]"><ArrowLeft :size="17"/>Volver al inicio</RouterLink><div class="mb-6"><p class="eyebrow">Lectura musical</p><h1 class="mt-1 text-3xl font-black">Mis partituras</h1><p class="mt-2 text-sm text-[#788780]">Abre una partitura MusicXML desde tu dispositivo para verla aquí.</p></div><section class="panel p-5 sm:p-7"><label class="flex min-h-[170px] cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-[#cbd9ce] bg-[#f7faf6] p-6 text-center"><span class="mb-3 grid h-12 w-12 place-items-center rounded-2xl bg-[#e7f1e8] text-[#36785e]"><Upload/></span><b>Selecciona tu archivo</b><span class="mt-1 text-sm text-[#849087]">XML o MusicXML desde tu dispositivo</span><input class="sr-only" type="file" accept=".xml,.musicxml" @change="choose"></label><p v-if="error" class="mt-3 text-sm text-red-600">{{error}}</p><p v-if="file" class="mt-3 flex items-center gap-2 text-sm font-semibold text-[#34785d]"><FileMusic :size="17"/>{{file.name}}</p></section><section v-if="file" class="panel mt-5 overflow-hidden p-3 sm:p-5"><Viewer :file="file"/></section><p v-else class="mt-5 rounded-2xl bg-[#eef3ef] p-4 text-sm leading-6 text-[#65776d]">OpenSheetMusicDisplay se carga únicamente cuando abres una partitura, para mantener ligera la aplicación.</p></div></template>